class Nat:
    def __init__(self, public_ip, first_port=40000):
        self.public_ip, self.next_port, self.table = public_ip, first_port, {}

    def outbound(self, private_ip, private_port):
        key = (private_ip, private_port)
        if key not in self.table:
            self.table[key] = self.next_port
            self.next_port += 1
        return self.public_ip, self.table[key]

    def inbound(self, public_port):
        for (ip, port), mapped in self.table.items():
            if mapped == public_port:
                return ip, port
        return None                            # no mapping: unsolicited traffic is dropped

nat = Nat("203.0.113.5")
print(nat.outbound("192.168.1.10", 51000))
print(nat.outbound("192.168.1.11", 51000))     # same private port, different device: different public port
print(nat.outbound("192.168.1.10", 51000))     # same flow reuses its mapping
print(nat.inbound(40001), nat.inbound(40099))

import struct

FLAGS = {0x02: "SYN", 0x10: "ACK", 0x08: "PSH", 0x01: "FIN", 0x04: "RST"}

def ip4(address):
    return bytes(int(part) for part in address.split("."))

def packet(src, dst, sport, dport, seq, ack, flags):
    tcp = struct.pack("!HHIIBBHHH", sport, dport, seq, ack, 5 << 4, flags, 65535, 0, 0)
    ip = struct.pack("!BBHHHBBH4s4s", 0x45, 0, 20 + len(tcp), 0, 0, 64, 6, 0, ip4(src), ip4(dst))
    return ip + tcp

capture = [   # synthetic packets built here, not a real capture
    packet("192.0.2.10", "198.51.100.20", 51234, 443, 1000, 0, 0x02),
    packet("198.51.100.20", "192.0.2.10", 443, 51234, 5000, 1001, 0x12),
    packet("192.0.2.10", "198.51.100.20", 51234, 443, 1001, 5001, 0x10),
]

def summarize(pkt):
    ihl = (pkt[0] & 0x0F) * 4
    src, dst = ".".join(map(str, pkt[12:16])), ".".join(map(str, pkt[16:20]))
    sport, dport, seq, ack, _, flags = struct.unpack("!HHIIBB", pkt[ihl:ihl + 14])
    names = ",".join(name for bit, name in FLAGS.items() if flags & bit)
    return f"{src}.{sport} > {dst}.{dport} [{names}] seq={seq} ack={ack}"

for pkt in capture:
    print(summarize(pkt))
